inline bool test_node_geometry(flight::types::NodeAny node, double x, double y, bool precise) {
  if (precise) {
    std::optional<std::function<double(flight::types::NodeAny, double, double)>> exact = hit_test_exact_registry.get(node->kind);
    if (exact.has_value()) {
      return (exact.value()(node, x, y) >= 0.0);
    }
  }
  std::optional<std::function<bool(flight::types::NodeAny, double, double)>> coarse = hit_test_registry.get(node->kind);
  return (flight::to_boolean(coarse) ? coarse.value()(node, x, y) : false);
}

bool hit_area_contains_point(flight::types::NodeAny node, flight::types::HitArea hit_area, double x, double y);

inline bool hit_test_node_region(flight::types::NodeAny source, double x, double y, std::optional<bool> precise = std::nullopt) {
  precise = precise.value_or(false);
  std::optional<flight::types::HitArea> hit_area = ([&]() -> std::optional<flight::types::HitArea> { auto optional_chain_receiver = flight::interaction::get_node_interaction_state(source); if (!optional_chain_receiver.has_value()) return std::nullopt; return optional_chain_receiver.value()->hit_area; }());
  if (hit_area.has_value()) {
    return hit_area_contains_point(source, hit_area.value(), x, y);
  }
  return test_node_geometry(source, x, y, precise.value());
}


